        ws.ActionType.EARN_WITHDRAW |
        ws.ActionType.ADD_COLLATERAL |
        ws.ActionType.REMOVE_COLLATERAL |
        ws.ActionType.BORROW |
        ws.ActionType.REPAY_DEBT |
        ws.ActionType.REWARDS
