#     Underscore Protocol License: https://github.com/underscore-finance/underscore-protocol/blob/master/LICENSE.md

# @version 0.4.3

interface UndyHq:
    def isValidAddr(_addr: address) -> bool: view
    def getAddr(_regId: uint256) -> address: view
    def undyToken() -> address: view

interface Switchboard:
    def isSwitchboardAddr(_addr: address) -> bool: view

interface LegoBook:
    def isLegoAddr(_addr: address) -> bool: view

struct Addys:
    hq: address
    undyToken: address
    ledger: address
    missionControl: address
    legoBook: address
    switchboard: address
    hatchery: address
    lootDistributor: address
    appraiser: address
    walletBackpack: address
    billing: address

# hq
UNDY_HQ_FOR_ADDYS: immutable(address)

# core addys
LEDGER_ID: constant(uint256) = 1
MISSION_CONTROL_ID: constant(uint256) = 2
LEGO_BOOK_ID: constant(uint256) = 3
SWITCHBOARD_ID: constant(uint256) = 4
HATCHERY_ID: constant(uint256) = 5
LOOT_DISTRIBUTOR_ID: constant(uint256) = 6
APPRAISER_ID: constant(uint256) = 7
WALLET_BACKPACK_ID: constant(uint256) = 8
BILLING_ID: constant(uint256) = 9


@deploy
def __init__(_undyHq: address):
    assert _undyHq != empty(address) # dev: invalid undy hq
    UNDY_HQ_FOR_ADDYS = _undyHq


########
# Core #
########


@view
@external
def getAddys() -> Addys:
    return self._generateAddys()


@view
@internal
def _getAddys(_addys: Addys = empty(Addys)) -> Addys:
    if _addys.hq != empty(address):
        return _addys
    return self._generateAddys()


@view
@internal
def _generateAddys() -> Addys:
    hq: address = UNDY_HQ_FOR_ADDYS
    return Addys(
        hq = hq,
        undyToken = staticcall UndyHq(hq).undyToken(),
        ledger = staticcall UndyHq(hq).getAddr(LEDGER_ID),
        missionControl = staticcall UndyHq(hq).getAddr(MISSION_CONTROL_ID),
        legoBook = staticcall UndyHq(hq).getAddr(LEGO_BOOK_ID),
        switchboard = staticcall UndyHq(hq).getAddr(SWITCHBOARD_ID),
        hatchery = staticcall UndyHq(hq).getAddr(HATCHERY_ID),
        lootDistributor = staticcall UndyHq(hq).getAddr(LOOT_DISTRIBUTOR_ID),
        appraiser = staticcall UndyHq(hq).getAddr(APPRAISER_ID),
        walletBackpack = staticcall UndyHq(hq).getAddr(WALLET_BACKPACK_ID),
        billing = staticcall UndyHq(hq).getAddr(BILLING_ID),
    )


##########
# Tokens #
##########


@view
@internal
def _getUndyToken() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).undyToken()


###########
# Helpers #
###########


# undy hq


@view
@external
def getUndyHq() -> address:
    return self._getUndyHq()


@view
@internal
def _getUndyHq() -> address:
    return UNDY_HQ_FOR_ADDYS


# utils


@view
@internal
def _isValidUndyAddr(_addr: address, _hq: address = empty(address)) -> bool:
    hq: address = _hq
    if _hq == empty(address):
        hq = UNDY_HQ_FOR_ADDYS

    # core departments
    if staticcall UndyHq(hq).isValidAddr(_addr):
        return True

    # lego book
    legoBook: address = staticcall UndyHq(hq).getAddr(LEGO_BOOK_ID)
    if legoBook != empty(address) and staticcall LegoBook(legoBook).isLegoAddr(_addr):
        return True

    # switchboard config
    switchboard: address = staticcall UndyHq(hq).getAddr(SWITCHBOARD_ID)
    if switchboard != empty(address) and staticcall Switchboard(switchboard).isSwitchboardAddr(_addr):
        return True

    return False


@view
@internal
def _isSwitchboardAddr(_addr: address) -> bool:
    switchboard: address = staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(SWITCHBOARD_ID)
    if switchboard == empty(address):
        return False
    return staticcall Switchboard(switchboard).isSwitchboardAddr(_addr)


@view
@internal
def _isLegoBookAddr(_addr: address) -> bool:
    legoBook: address = staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(LEGO_BOOK_ID)
    if legoBook == empty(address):
        return False
    return staticcall LegoBook(legoBook).isLegoAddr(_addr)


###############
# Departments #
###############


# ledger


@view
@internal
def _getLedgerId() -> uint256:
    return LEDGER_ID


@view
@internal
def _getLedgerAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(LEDGER_ID)


# mission control


@view
@internal
def _getMissionControlId() -> uint256:
    return MISSION_CONTROL_ID


@view
@internal
def _getMissionControlAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(MISSION_CONTROL_ID)


# lego book


@view
@internal
def _getLegoBookId() -> uint256:
    return LEGO_BOOK_ID


@view
@internal
def _getLegoBookAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(LEGO_BOOK_ID)


# switchboard


@view
@internal
def _getSwitchboardId() -> uint256:
    return SWITCHBOARD_ID


@view
@internal
def _getSwitchboardAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(SWITCHBOARD_ID)


# hatchery


@view
@internal
def _getHatcheryId() -> uint256:
    return HATCHERY_ID


@view
@internal
def _getHatcheryAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(HATCHERY_ID)


# loot distributor


@view
@internal
def _getLootDistributorId() -> uint256:
    return LOOT_DISTRIBUTOR_ID


@view
@internal
def _getLootDistributorAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(LOOT_DISTRIBUTOR_ID)


# appraiser


@view
@internal
def _getAppraiserId() -> uint256:
    return APPRAISER_ID


@view
@internal
def _getAppraiserAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(APPRAISER_ID)


# wallet backpack


@view
@internal
def _getWalletBackpackId() -> uint256:
    return WALLET_BACKPACK_ID


@view
@internal
def _getWalletBackpackAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(WALLET_BACKPACK_ID)


# billing


@view
@internal
def _getBillingId() -> uint256:
    return BILLING_ID


@view
@internal
def _getBillingAddr() -> address:
    return staticcall UndyHq(UNDY_HQ_FOR_ADDYS).getAddr(BILLING_ID)

contracts/modules/YieldLegoData.vy.content:
#     Underscore Protocol License: https://github.com/underscore-finance/underscore-protocol/blob/master/LICENSE.md

# @version 0.4.3

uses: addys

import contracts.modules.Addys as addys

from interfaces import WalletStructs as ws
from ethereum.ercs import IERC20

event AssetOpportunityAdded:
    asset: indexed(address)
    vaultAddr: indexed(address)

event AssetOpportunityRemoved:
    asset: indexed(address)
    vaultAddr: indexed(address)

event LegoPauseModified:
    isPaused: bool

event LegoFundsRecovered:
    asset: indexed(address)
    recipient: indexed(address)
    balance: uint256

# config
isPaused: public(bool)

# asset opportunities
assetOpportunities: public(HashMap[address, HashMap[uint256, address]]) # asset -> index -> vault addr
indexOfAssetOpportunity: public(HashMap[address, HashMap[address, uint256]]) # asset -> vault addr -> index
numAssetOpportunities: public(HashMap[address, uint256]) # asset -> number of opportunities

# mapping
vaultToAsset: public(HashMap[address, address]) # vault addr -> underlying asset

# lego assets (iterable)
assets: public(HashMap[uint256, address]) # index -> asset
indexOfAsset: public(HashMap[address, uint256]) # asset -> index
numAssets: public(uint256) # num assets

MAX_VAULTS: constant(uint256) = 40
MAX_ASSETS: constant(uint256) = 20
MAX_RECOVER_ASSETS: constant(uint256) = 20


@deploy
def __init__(_shouldPause: bool):
    self.isPaused = _shouldPause
    self.numAssets = 1 # not using 0 index


#########
# Views #
#########


# is lego asset


@view
@external
def isLegoAsset(_asset: address) -> bool:
    return self._isLegoAsset(_asset)


@view
@internal
def _isLegoAsset(_asset: address) -> bool:
    return self.indexOfAsset[_asset] != 0


# vault opportunities


@view
@external
def getAssetOpportunities(_asset: address) -> DynArray[address, MAX_VAULTS]:
    numOpportunities: uint256 = self.numAssetOpportunities[_asset]
    if numOpportunities == 0:
        return []
    opportunities: DynArray[address, MAX_VAULTS] = []
    for i: uint256 in range(1, numOpportunities, bound=MAX_VAULTS):
        opportunities.append(self.assetOpportunities[_asset][i])
    return opportunities


# all assets registered


@view
@external
def getAssets() -> DynArray[address, MAX_ASSETS]:
    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return []
    assets: DynArray[address, MAX_ASSETS] = []
    for i: uint256 in range(1, numAssets, bound=MAX_ASSETS):
        assets.append(self.assets[i])
    return assets


################
# Registration #
################


@view
@external
def isAssetOpportunity(_asset: address, _vaultAddr: address) -> bool:
    return self._isAssetOpportunity(_asset, _vaultAddr)


@view
@internal
def _isAssetOpportunity(_asset: address, _vaultAddr: address) -> bool:
    return self.indexOfAssetOpportunity[_asset][_vaultAddr] != 0


# add asset opportunity


@internal
def _addAssetOpportunity(_asset: address, _vaultAddr: address):
    if self.indexOfAssetOpportunity[_asset][_vaultAddr] != 0:
        return
    if empty(address) in [_asset, _vaultAddr]:
        return

    # add asset opportunity
    aid: uint256 = self.numAssetOpportunities[_asset]
    if aid == 0:
        aid = 1 # not using 0 index
    self.assetOpportunities[_asset][aid] = _vaultAddr
    self.indexOfAssetOpportunity[_asset][_vaultAddr] = aid
    self.numAssetOpportunities[_asset] = aid + 1

    # add mapping
    self.vaultToAsset[_vaultAddr] = _asset

    # add asset
    self._addAsset(_asset)

    log AssetOpportunityAdded(asset=_asset, vaultAddr=_vaultAddr)


# remove asset opportunity


@internal
def _removeAssetOpportunity(_asset: address, _vaultAddr: address):
    numOpportunities: uint256 = self.numAssetOpportunities[_asset]
    if numOpportunities == 0:
        return

    targetIndex: uint256 = self.indexOfAssetOpportunity[_asset][_vaultAddr]
    if targetIndex == 0:
        return

    # update data
    lastIndex: uint256 = numOpportunities - 1
    self.numAssetOpportunities[_asset] = lastIndex
    self.indexOfAssetOpportunity[_asset][_vaultAddr] = 0

    self.vaultToAsset[_vaultAddr] = empty(address)

    # shift to replace the removed one
    if targetIndex != lastIndex:
        lastVaultAddr: address = self.assetOpportunities[_asset][lastIndex]
        self.assetOpportunities[_asset][targetIndex] = lastVaultAddr
        self.indexOfAssetOpportunity[_asset][lastVaultAddr] = targetIndex

    # remove asset
    if lastIndex <= 1:
        self._removeAsset(_asset)

    log AssetOpportunityRemoved(asset=_asset, vaultAddr=_vaultAddr)


# add asset


@internal
def _addAsset(_asset: address):
    if self.indexOfAsset[_asset] != 0:
        return

    aid: uint256 = self.numAssets
    if aid == 0:
        aid = 1 # not using 0 index
    self.assets[aid] = _asset
    self.indexOfAsset[_asset] = aid
    self.numAssets = aid + 1


# remove asset


@internal
def _removeAsset(_asset: address):
    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return

    targetIndex: uint256 = self.indexOfAsset[_asset]
    if targetIndex == 0:
        return

    # update data
    lastIndex: uint256 = numAssets - 1
    self.numAssets = lastIndex
    self.indexOfAsset[_asset] = 0

    # shift to replace the removed one
    if targetIndex != lastIndex:
        lastAsset: address = self.assets[lastIndex]
        self.assets[targetIndex] = lastAsset
        self.indexOfAsset[lastAsset] = targetIndex


# num lego assets (true number, use `numAssets` for iteration)


@view
@external
def getNumLegoAssets() -> uint256:
    return self._getNumLegoAssets()


@view
@internal
def _getNumLegoAssets() -> uint256:
    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return 0
    return numAssets - 1


###########
# General #
###########


# fill mini addys


@view
@internal
def _getMiniAddys(_miniAddys: ws.MiniAddys = empty(ws.MiniAddys)) -> ws.MiniAddys:
    if _miniAddys.ledger != empty(address):
        return _miniAddys
    return ws.MiniAddys(
        ledger = addys._getLedgerAddr(),
        missionControl = addys._getMissionControlAddr(),
        legoBook = addys._getLegoBookAddr(),
        appraiser = addys._getAppraiserAddr(),
    )


# activate


@external
def pause(_shouldPause: bool):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    assert _shouldPause != self.isPaused # dev: no change
    self.isPaused = _shouldPause
    log LegoPauseModified(isPaused=_shouldPause)


# recover funds


@external
def recoverFunds(_recipient: address, _asset: address):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    self._recoverFunds(_recipient, _asset)


@external
def recoverFundsMany(_recipient: address, _assets: DynArray[address, MAX_RECOVER_ASSETS]):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    for a: address in _assets:
        self._recoverFunds(_recipient, a)


@internal
def _recoverFunds(_recipient: address, _asset: address):
    assert empty(address) not in [_recipient, _asset] # dev: invalid recipient or asset
    balance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    assert balance != 0 # dev: nothing to recover

    assert extcall IERC20(_asset).transfer(_recipient, balance, default_return_value=True) # dev: recovery failed
    log LegoFundsRecovered(asset=_asset, recipient=_recipient, balance=balance)

